import type { Story } from "./stories";

export const stories1800: Record<number, Story> = {
	1800: {
		index: 1800,
		text: `<p>Seeing the men trapped in his cage, doomed to be the dreadful giant's next meal, fills you with an uncontrollable rage. You decide that the giant must die for his sins.</p>
<p><b>No Skill:</b> You notice a large boulder up the slope from the giant's pavilion. If you can get it rolling, it should crush the giant in his sleep. It takes a fair amount of digging and pushing, but you finally get it rolling. The boulder crashes into the pavilion with a resounding crash, sending men and debris flying. You assume the giant was slain, as you see no sign of him again. [D1/S1]</p>
<p><b>Stealth and Stealing:</b> Late in the night, you creep into the tent, your movements more than covered by the sound of the giant's hideous snoring. His eyes flash open just in time to see your face as you deliver deadly retribution. One of the men you freed is a wealthy merchant, who gladly pays you a reward for his rescue. [D1/W+1 (Max: Respectable)]</p>
<p><b>Weapon Use:</b> You charge into the pavilion, scimitar in hand. You catch the monster by surprise, dealing a terrible blow to his leg. Despite the pain of his wound, the creature is mighty in battle, and in just a few moments you are left a bleeding wreck in the back of the tent. Fortunately, the cage was destroyed in the fight, and one of the freed men drags you with him when he makes his escape. [D2/S1/<em>Crippled</em>]</p>`,
	},
	1801: {
		index: 1801,
		text: `<p>You enter a large clearing, dominated by a large pavilion. You see an enormous black giant laboriously lashing a struggling captive to a spit, no doubt intended for the large fire.</p>
<p><b>No Skill:</b> Being careful that the giant does not notice you, you sneak behind the pavilion and find a large barrel full of water. You push the barrel over, and the water flows into the fire, extinguishing it in a great cloud of smoke and ash! In the confusion that follows, you quickly free the young man and flee, leaving the pavilion far behind you. [D1/S1/Stealth and Stealing]</p>
<p><b>Storytelling:</b> You call to the giant, offering to share with him a tale so wondrous it is unlike any he has ever heard before, if he agrees to release his prisoner. The giant agrees on the condition that if he dislikes your tale, you will take the man's place! When he finally stops laughing from the Tale of the Barber's Third Brother, he agrees to release both you and the other man. [D1/S1]</p>`,
	},
	1802: {
		index: 1802,
		text: `<p>The sounds of angry men can be heard over the next hill. When you go to investigate, you see a band of spearmen poking and prodding at an enormous black-skinned man trapped under a net.</p>
<p><em>Do you come to the aid of the unfortunate giant?</em></p>
<p><em>If yes:</em> The warriors are surprised that anyone would come to the aid of the giant they had worked so hard to capture. The giant is also surprised, but not enough not to lash out in the confusion you created. Freed from the net, he quickly overwhelms the soldiers. He is grateful for your assistance, and gives you a pouch of gems. [D1/S1/W+1 (Max: Rich)]</p>
<p><em>If no:</em> You watch as the soldiers bind the mighty giant. One of the spearmen tells you of the giant's cannibalistic ways, and you know you were right not to intervene. [D1/S1]</p>`,
	},
	1803: {
		index: 1803,
		text: `<p>The pearl beds here are renowned throughout the world for the size and quality of the pearls that can be found. You venture to try the art yourself. It proves more difficult than you expect, and soon, your lungs burning for air, you surge towards the surface. But as you rise, your foot is caught in the ragged coral! Fighting panic, you struggle to break free, the pain in your lungs growing greater every moment. When you cannot stand it any longer, your heart screams a prayer to the All-Merciful.</p>
<p><b>No Skill:</b> A moment later your vision fades. You awaken on the shore, with no memory of how you came to be there. [D1/Piety]</p>
<p><b>Luck:</b> With a mighty pull, you wrench your leg free and discover that it was not the coral, but the strap of a leather bag that had entrapped you. Pulling it to the surface, you realize that it is a saddlebag of exotic workmanship! Praise Allah! [D1/S1/<b>Magic Saddlebags</b>]</p>`,
	},
	1804: {
		index: 1804,
		text: `<p>A dear friend from your childhood has offered to show you the fine art of pearl diving. You stand safely on the shore as he disappears beneath the waves. You watch for a very long time, but there is no sign of your friend. You grow fearful for your bosom friend, and begin to pray to Allah that he will be safe.</p>
<p><b>No Skill:</b> Suddenly, the water bubbles and your friend finally breaks through to the surface, barely conscious. Sadly, in his distress, he lost hold of the pearls he had collected. [S1]</p>
<p><b>Seamanship:</b> Your friend needs help! Calling upon your experience as a sailor, you dive into the water, swimming as fast as you can. You find your friend floating limp in the water, and you hoist him to safety. Your sigh of relief turns into a shout of joy as he shares with you his collection of fresh pearls! [D1/S1/W+2 (Max: Respectable)]</p>`,
	},
	1805: {
		index: 1805,
		text: `<p>You decide to try your hand at pearl diving, hoping to make a small fortune. Holding your breath, you plunge to the bottom. But instead of finding a pearl bed, you find an ancient shipwreck! You try to get close enough to investigate, but a great shark immerges from the wreck!</p>
<p><b>No Skill:</b> As soon as you see the shark, you swim for the safety of the shore. You barely reach an outcropping of rock as the shark snaps at your heels! You thank Allah for delivering you from a terrible fate. [S1/Seamanship]</p>
<p><b>Weapon Use:</b> All you have to defend yourself is your pearl knife. Against such a terrifying creature, you cannot imagine it will be enough, but you know you cannot out-swim the greatest hunter of the deep! As the beast approaches, you pray to the Most High for true aim and stab at its sensitive nose. Confused by the sudden pain and the smell of its own blood, the shark writhes about. You grab a loose amphora from the wreckage, and flee to the safety of shore. Inside the amphora you find an interesting bauble. [D1/S1/<b>Ionian Gems</b>]</p>`,
	},
	1806: {
		index: 1806,
		text: `<p>Walking along the shore, you discover a number of men in small boats. You realize that they are pearl divers! You decide you would like to attempt the dangerous feat, but you know that some training might just save your life.</p>
<p><b>No Skill:</b> You approach a few of the divers, but they refuse to share their secrets with you. They offer to sell you some of their pearls, but you politely decline their offer. [S1]</p>
<p><b>Bargaining and Evaluation:</b> You find an old man repairing his ropes. He is too old to dive himself and seems delighted to have a healthy young assistant. He shows you the basic techniques, and before long you are pulling great oysters up from the bottom! [D1/W+1 (Max: Respectable)]</p>`,
	},
	1807: {
		index: 1807,
		text: `<p>You join some pearl divers, hoping to find some of the precious stones at the bottom of the sea. After a long dive, you emerge on the surface to discover that all the other divers have vanished. Instead, you see a company of the Sultan's soldiers! They seize you and accuse you of stealing from the Sultan's pearl bed!</p>
<p><b>No Skill:</b> You beg the Vizier for mercy. In exchange for testimony against the other divers, and the payment of a stiff bribe, he agrees to release you. [D-1/W-1 (Min: Poor)/Bargaining and Evaluation]</p>
<p><b>Courtly Graces:</b> With your understanding of ways of the nobility, you are able to construct an effective defense before the Sultan. The Vizier is embarrassed and humiliated by the ease with which you turn his arguments against him. The Sultan gives you gifts for your troubles, and sends you on your way. But the Vizier is determined to get his revenge! [D1/S1/W+1 (Max: Rich)/<em>Pursued</em>]</p>
<p><b>Acting and Disguise:</b> You are able to convince the captain that you are actually a secret envoy of the Sultan, sent to discover those who were poaching on his pearl beds. By the time he realizes your trick, you have left the Sultan's lands along with a nice little bag full of precious pearls. [S1/W+2 (Max: Princely)]</p>`,
	},
	1808: {
		index: 1808,
		text: `<p>You learn that not all pearl divers are honest, hard-working men. Some of them are thieves! As you emerge from the water with a basket full of pearls, you feel the sharp prick of a knife in your back!</p>
<p><b>No Skill:</b> You see no choice. The pearls are not worth your life. You surrender your hard-earned wealth, and the rogue vanishes before you can turn around. [S1]</p>
<p><b>Stealth and Stealing:</b> Very carefully and stealthily, you draw your own knife while pretending to turn over the pearls. As soon as the thief grabs your pearl basket, you turn on him and attack! The knife fight is short and vicious, but you are victorious in the end. [D1/S1/W+2 (Max: Respectable)/<em>Wounded</em>]</p>`,
	},
	1809: {
		index: 1809,
		text: `<p>In a marketplace, you observe a strange little man charming a snake with a flute. You are almost entranced by the rhythmic movements and music of the snake charmer. You realize that this could be a very useful skill if you ever encounter a snake. After his performance, you approach him and try to convince him to teach you his secrets.</p>
<p><b>No Skill:</b> The man listens to your offers but insists that he cannot teach you. Only members of his religious sect are permitted to know the art that he has demonstrated. Disappointed, you continue your journey. [S1]</p>
<p><b>Bargaining and Evaluation:</b> After much haggling, you convince the man to show you his methods. [S1/W-1 (Min: Poor)/Wilderness Lore]</p>`,
	},
	1810: {
		index: 1810,
		text: `<p>Resting near a secluded well, you are shocked to see a serpentine creature emerge from the water. At the tail of the snake is a human head! Once you get over your initial shock, you discover that it is capable of speech, and you begin to converse with the creature. You learn that it has become lost in a land far from home.</p>
<p><b>No Skill:</b> Fearing that the beast means to devour you, you quickly agree to help as much as you can. You eventually learn that it has wandered from the Mughal lands far to the east, and you point out the direction it should travel. [S1]</p>
<p><b>Storytelling:</b> You remember tales from your travels in the Mughal lands of such creatures, called Nāgah. In those lands it is said that they are intelligent and often generous when treated with respect. Bowing, you address the beast as if it were the Sultan himself. Flattered by such treatment, the Nāgah grants you a mystical boon as reward for your kindness and aid. [D1/S1/Courtly Graces/<em>Blessed</em>]</p>`,
	},
	1811: {
		index: 1811,
		text: `<p>A band of magicians has discovered the means to control the serpents in the area. You realize that you will have to make a deal with them if you are going to be able to leave with your skin intact.</p>
<p><b>No Skill:</b> The magicians want to move on to wealthier areas, and they decide that you are just the person they need to make it possible. You agree to use your connections to set them up in the next kingdom. When you arrive in the next valley, you instead approach a respected vizier and warn him of the approaching cult. You are rewarded for your diligence. [D1/S1/W+1 (Max: Respectable)/Beguiling]</p>
<p><b>Seduction:</b> Perhaps you tried too hard to convince the cultists to spare your life. It seems that you have caught the eye of one of the magicians, and now you are forced into bondage! [S1/<em>Enslaved</em>]</p>`,
	},
	1812: {
		index: 1812,
		text: `<p>As you cross the spine of a ridge, you see something shining in the sun. You approach to investigate and discover a broad pit filled with snakes. In the center stands a small pile of rocks, upon which sits a red stone statue of a serpent with rubies for eyes. So large are the rubies that they reflect the rays of the sun from over a league away!</p>
<p><b>No Skill:</b> You must have the statue for yourself! You run across the shallow pit, hoping to move fast enough to reach the stones unhurt. Without pausing, you grab the stone statue and continue running. But your feet slip on the slithering forms beneath you, and you feel numerous little bites on your legs and ankles. By the time you reach the far side, the venom of many snakes course through your blood. Three days later you are found, nearly paralyzed, by the side of the road. You have no idea what fate befell the statue. [S1/<em>Crippled</em>]</p>
<p><b>Scholarship:</b> You remember that snakes are cold blooded. If you wait until the coldest part of the night, they should be so sluggish that you can retrieve the statue without danger. Your wisdom proves true, and you easily retrieve the statue without disturbing the snakes. [D1/S1/<b>Carnelian Idol</b>]</p>`,
	},
	1813: {
		index: 1813,
		text: `<p>The pillars of the crumbling marble structure were carved in the image of great serpents. But rumors of great wealth within spur you to explore its shadowy depths. As you enter, you are startled by the sudden appearance of a beautiful woman, dressed in a long gray gown.</p>
<p><b>No Skill:</b> You are entranced by the stately woman, who lures you deeper into the ancient ruin. As you sit together, drinking, you become aware of a serpentine form wrapping itself around you. Your eyes follow the curve of the snake's tail. To your horror, you realize that the woman is transforming into an enormous serpent! Your screams echo off the marble walls as you flee into the forest in blind panic. [S1/<em>Insane</em>]</p>
<p><b>Courtly Graces:</b> With great respect, you treat the matronly woman as though she were an important official. She seems pleased with your manners and reveals that she is the last of a race of shape-shifting serpents! Your mind reels from her words. Before she allows you to depart, she grants you the gift of ancient scrolls of serpentine wisdom. [D1/S1/Scholarship]</p>`,
	},
	1814: {
		index: 1814,
		text: `<p>Against the advice of your native guide, you enter the serpent-haunted wood in pursuit of the treasures rumored to be within. If your guide had only told you how big the serpents were, you might have taken his advice. Now you find yourself facing a snake far larger than you could ever have imagined.</p>
<p><b>No Skill:</b> The serpent is so long you cannot see both ends of it at once! You could never hope to vanquish a creature that could crush elephants in its coils. You have no choice but to flee from the forest empty-handed. [S1/Wisdom]</p>
<p><b>Luck:</b> Monsters the size of this serpent may be strong and powerful, but they don't move very quickly. You deftly avoid getting entangled in its coils and retrieve the lost treasures! [D1/W+1 (Max: Princely)/Stealth and Stealing]</p>`,
	},
	1815: {
		index: 1815,
		text: `<p>You stagger into the village, half-dead from the serpent venom burning in your veins. If you do not get some kind of help, you know that you will soon be dead.</p>
<p><b>No Skill:</b> The only villager who offers to assist you is a twisted old crone. She agrees to provide you with an anti-venom if you agree to aid her with a certain task that she cannot do on her own. Reluctantly, you agree to her terms. After she has cured you, she describes what she needs you to do. [D1/S1/<em>Under Geas</em>]</p>
<p><b>Vizier, Sultan, Respected</b> (All mandatory): The people of the village rush to your aid. After three days, your fever breaks, and you are able to continue on your journey. [D-1/S1]</p>`,
	},
	1816: {
		index: 1816,
		text: `<p>You are traveling through a region that lately has been plagued by snakes of all sizes and types. The people would doubtless be grateful if you could find some way to rid them of this scourge.</p>
<p><b>No Skill:</b> You remember passing by a caravan from the Islands of Camphor recently. The merchant tried to sell you some snake-repelling oil from that region. It costs you a fair amount of money, but you are able to purchase enough oil to aid the locals. [D1/S1/W-1 (Min: Poor)/Bargaining and Evaluation]</p>
<p><b>Enduring Hardship:</b> You know of a certain guru who makes his home high on a rugged pinnacle of rock. He is said to have knowledge of all the creatures that crawl on their bellies. It is a difficult and arduous journey to the hermit's pillar, but you finally reach him. He obliges you to join him in a month-long fast before revealing his secret knowledge of keeping snakes at bay. [D1/S1/Wilderness Lore]</p>`,
	},
	1817: {
		index: 1817,
		text: `<p>Your traveling companion has been injured by a wild dog in the woods, and as you hasten to find help, you trip and fall down a hillside. When you reach the bottom of the slippery slope, you shake your head to clear your vision. You are about to rise when you realize that you are staring straight into the eyes of a deadly asp!</p>
<p><b>No Skill:</b> This is a very dangerous snake, and very fast. You cannot run; your only hope is to lie very still and hope that it does not decide to strike.</p>
<p><em>Roll two dice, adding one each for Enduring Hardship, Stealth and Stealing, and Wilderness Lore:</em></p>
<p>❖ 2–4: Unable to sit still long enough, you involuntarily jerk away, and the asp sinks its deadly fangs into your neck! As you lie there paralyzed, a passing merchant happens to find you and bring you to a healer before you die. Alas, the venom still left some effect of its poison. [Luck/<em>Crippled</em>]</p>
<p>❖ 5–9: You lie still so long that your muscles burn with pain. Finally the snake grows bored and slithers off. You breathe a sigh of relief. [D1/S1]</p>
<p>❖ 10+: Suddenly, you hear a beautiful voice singing behind you. The asp sways to the sound, entranced. Seeing your opportunity, your hand flashes out to grab the serpent and fling it away. You turn to view your savior, but she is nowhere to be found! [D1/S1/Quick Thinking]</p>
<p><b>Appearance:</b> You freeze in place, hoping that the asp will not strike. You hear motion behind you, and pray that it is not another serpent. To your amazement, you hear a woman singing in a clear, melodious voice. The snake is charmed by the music, and soon slithers over you towards the singer. Amazed, you turn to see your savior. Your eyes fall upon a most magnificent youth, truly an angel from heaven itself! [D1/S1/<em>Love Struck</em>]</p>`,
	},
	1818: {
		index: 1818,
		text: `<p>Lost in the woods, you hear a cry for help. When you investigate, you discover that the cry came from a young maiden. She has fallen into a den of vipers!</p>
<p><b>No Skill:</b> Seizing up a firebrand, you leap into the pit to rescue the girl. Using the fire to hold the vipers at bay, you help the girl climb to freedom. As you follow her out, you feel a sharp pain in your heel! [D1/S1/<em>Diseased</em>]</p>
<p><b>Seamanship:</b> Your knowledge of knots and ropes is very valuable in moments like this! You rapidly tie together some vines and cords from the nearby trees and brush. Securing the hastily constructed rope to a branch hanging over the pit, you leap over to where the girl awaits. You hoist her onto your back and yell for her to hold on tight while you climb to safety. You learn that she is the daughter of a local magistrate, who rewards you handsomely. [D1/S1/W+1 (Max: Respectable)/<em>Respected</em>]</p>`,
	},
	1819: {
		index: 1819,
		text: `<p>Leaning against a tree is a man feverish from poison. It is clear that he will soon expire if you do not aid him.</p>
<p><b>No Skill:</b> Using your knife, you cut open the wound so you can suck the poison out before it kills the man. Treating him with some herbs in your bag, it takes two days before he is coherent enough to speak. He will eventually recover. In exchange for your unexpected aid, he offers to guide you to the location of a long-lost fortune. [D1/S1/Opportunity to enter the Lake of Colors]</p>
<p><b>Magic:</b> You know that it is too late to save this man with simple medicine, so you use your mystical arts to save his life. When the devout dervish learns what you have done on his behalf, he curses you for corrupting his body with your black magic! [S1/Piety/<em>Accursed</em>]</p>`,
	},
	1820: {
		index: 1820,
		text: `<p>A giant serpent has made a home for itself in the heart of a small village, and has taken to feeding on the livestock. It strikes only at night, and the villagers cannot locate it during the day.</p>
<p><b>No Skill:</b> You convince a number of the villagers to stand watch all night, so they can see the serpent. Alas! A young boy falls asleep at his post and is that night's victim! You are too distraught to be of any further aid to the villagers. [D-1/S1/<em>Grief Stricken</em>]</p>
<p><b>Acting and Disguise:</b> Judging by the size of the discarded snake skin you find, even if the villagers could locate the serpent, it would be too much for them to handle. Dressing in your most magnificent robes, you approach a nearby fortress. The captain is fooled by your attitude and agrees to dispatch his soldiers as you command. You realize it is best for you to leave the area before he discovers your deception. [D1/S1]</p>
<p><b>Storytelling:</b> On the highway leaving the Sultan's kingdom, you tell your tale to all who will listen. A wise imam hears your tale and is moved to pray on your behalf. Under the holy man's guidance, you make generous gifts to the poor. Afterwards, you are still the wrong gender, but your soul feels much cleansed. [D1/S1/Piety/<em>Sex-Changed</em>]</p>`,
	},
	1821: {
		index: 1821,
		text: `<p>You broke your lover's heart, but what is that to you? You got what you wanted. Maybe you should have been suspicious when the servant gave you a gift from the jilted soul. But the water was clean and clear and just a little sweet. When the odd sensations fade, you realize that you are transformed!</p>
<p><b>No Skill:</b> You are so mistreated by members of your former sex trying to coerce favors from you, you are reduced to tears. You vow before Allah that you will never again seduce another! [S1/Lose Seduction/<em>Sex-Changed</em>]</p>
<p><b>Luck:</b> In total despair, you are about to take your own life. A passing dervish interrupts your preparations. You tell him your sorry tale, and he agrees to pray with you for the mercy of the Most High. The next morning, you are returned to your normal form. You can't be sure if the effect wore off, or if it was a gift from Allah. [D1/S1/Lose <em>Sex-Changed</em>/Lose <em>Beast Form</em>]</p>`,
	},
	1822: {
		index: 1822,
		text: `<p>You have been put under a most terrible spell! Tricked by your cunning guide to drink from the mysterious spring, you have found your gender reversed. Now he intends to sell you into slavery!</p>
<p><b>No Skill:</b> Your prayers for deliverance are answered, but in a form far from what you had hoped. A magician tells you that when your body is rebuilt after leaving this plane, it will return to its true form. Not realizing what he means by a plane, you accept his offer without thinking. Now you are in the strange and frightening land of the djinn! [D1/Lose <em>Sex-Changed</em>/Move to the Dusky Land and have an immediate encounter]</p>
<p><b>Appearance:</b> Despite your prayers for aid from the divine, you are auctioned off for a fine price. [S1/<em>Sex-Changed</em>/<em>Enslaved</em>]</p>`,
	},
	1823: {
		index: 1823,
		text: `<p>When the Sultan caught you in the arms of his daughter, he needed a way to punish you both. Being particularly cruel, he forces you to drink from a magical well that has the power to transform man to woman and woman to man!</p>
<p><b>No Skill:</b> Expelled from his kingdom and shorn of your identity, you sink to your knees in supplication to the All-Merciful. When you rise, you see a vision of holy Mecca. You determine to make a pilgrimage. [D1/S1/<em>Sex-Changed</em>/<em>On Pilgrimage</em>—if you are still <em>Sex-Changed</em> when the pilgrimage is complete, lose <em>Sex-Changed</em>]</p>`,
	},
	1824: {
		index: 1824,
		text: `<p>That ill-mannered brute of a hunchback tricked you! He swore that the water was safe to drink, but now you find that your gender has been reversed. How can you complete your quest in this condition?</p>
<p><b>No Skill:</b> You are determined to give the hunchback the beating of his life, but you are unfamiliar with your new form and too clumsy to overcome him. He escapes your wrath... for now. [S1/<em>Sex-Changed</em>]</p>
<p><b>Weapon Use (mandatory):</b> Your new form might be unfamiliar and awkward, but you still know how to use a sword! The hunchback will regret his decision to trick you for all of the last three minutes of his life. Unfortunately, you are seen dispensing your justice, and soon find yourself in the Sultan's dungeons! [S1/<em>Sex-Changed</em>/<em>Imprisoned</em>]</p>`,
	},
	1825: {
		index: 1825,
		text: `<p>After that insult, you have no choice but to challenge your rival to a duel to the death. You are lead by your second to a secluded oasis. Your rival invites you to take a cooling drink before the battle so the fight will be fair.</p>
<p><b>No Skill:</b> You drink deeply from the cool, sweet waters of the spring. To your amazement, your reflection in the water changes! Your gender has been reversed! You look to your treacherous rival to discover an identical transformation taking place. "You fool! The curse could not be lifted until I tricked another into drinking from the spring. Now I am free at last!" You see to it that the rogue dies free. [S1/Weapon Use/<em>Sex-Changed</em>]</p>
<p><b>Quick Thinking:</b> Distrustful of your foe, you refuse the offer and prepare for the duel. Seeing that the ploy was discovered, your rival drops down and begs you for your mercy, revealing the plan to trick you into drinking so you too would suffer a change of sex. Disgusted by the groveling, you leave the miserable wretch to suffer. [D1]</p>`,
	},
	1826: {
		index: 1826,
		text: `<p>The black magician stands on the small island in the middle of the shallow lake, his smug look setting your blood aboil. His unspeakable acts have earned the ire of the Sultan, and you intend to collect his reward. You order your men to attack, but when the first of them reaches the water, they all fall back in confusion. Those who merely touched the water of the accursed spring have been transformed into women!</p>
<p><b>No Skill:</b> The soldiers will not stand before such vile sorcery. They refuse to attack, and quickly begin to desert. The evil magician laughs scornfully as you are forced to retreat. [S1]</p>
<p><b>Seamanship:</b> If touching the water is the cause of the curse, then surely a boat will protect you from the dark magic. You seize a local fisherman's dinghy and cast off. When the magician realizes that you have seen through his ploy, he speaks some words that should not be understood, and vanishes from the island. Though you did not slay the sorcerer, the Sultan is pleased that you have chased him off and gives you half the reward. [D1/W+1 (Max: Rich)/Quick Thinking]</p>`,
	},
	1827: {
		index: 1827,
		text: `<p>While crossing the desert, a sandstorm robbed you of your water bag and you were forced to drink from the first spring you could find. Sadly for you, one of them was a mysterious spring which reverses the gender of all who drink its waters! You travel from village to village seeking a wise man who can cure you of your bizarre ailment. You finally find a magician who agrees to transform you back in exchange for a favor in a distant land.</p>
<p><em>Do you agree to his terms?</em></p>
<p><em>If no:</em> He sends you on your way, still afflicted by the curse of the waters. [S1/<em>Sex-Changed</em>]</p>
<p><em>If yes:</em> The magician casts a spell upon you. You are returned to your normal form, but now you have no control over your own movements! [D1/Lose <em>Sex-Changed</em>/Lose <em>Beast Form</em>/<em>Ensorcelled</em>]</p>`,
	},
	1828: {
		index: 1828,
		text: `<p>You have learned of a corrupt Vizier who uses a mysterious sex-changing spring to destroy his political rivals. The Sultan is too busy with his harem to pay attention to the actions of his advisor.</p>
<p><b>No Skill:</b> After much wine, you convince one of the Vizier's own guards to loan you his uniform. Breaking into the Vizier's palace, you locate the magic spring and claim a small sample. Adding the enchanted water to the Vizier's wine, you are delighted when he suffers the same fate as so many of his rivals. No one would believe that the frail woman was actually the Vizier. [D1/Stealth and Stealing]</p>
<p><b>Courtly Graces:</b> You approach the court in an attempt to get an audience with the Sultan of this land. If you could meet with him, perhaps you could convince him of the Vizier's wicked nature. But the evil advisor catches wind of your plans, and before you can see the Sultan, he slips some enchanted water into your bath, and you find yourself his latest victim! [S1/<em>Sex-Changed</em>]</p>`,
	},
	1829: {
		index: 1829,
		text: `<p>You knew you made a mistake as soon as the water of the mysterious spring had touched your lips. Now you have been transformed into the opposite gender! What price would you not pay to be rid of such a terrible curse?</p>
<p><b>No Skill:</b> In a nearby village, a twisted old crone claims to have the solution to your problem. But the price she demands is painfully steep: she demands a Treasure or bags of gold.</p>
<p><em>Do you pay her price?</em></p>
<p><em>If you are at a Wealth level of Respectable or less or will not pay:</em> She sends you on your way, still changed. [S1/<em>Sex-Changed</em>]</p>
<p><em>If you have a Wealth level of Rich or greater and wish to pay:</em> Give her one of your Treasures (return it to the deck). If you have no Treasures, then you give her your gold. After handing over payment, she feeds you bitter herbs and speaks curious words you would not dare try to repeat. You are furious when you discover that she has merely swapped one curse for another! [S1/Choice of <b>Lose Treasure</b> or W-3 (Min: Penniless)/Lose <em>Sex-Changed</em>/<em>Beast Form</em>]</p>
<p><b>Bargaining and Evaluation:</b> You encounter a traveling peddler who offers to sell you a magical talisman that will cure you of your curse. You eagerly pay the charlatan. He is long gone before you discover that the totem has no effect on your altered gender, but it may still be valuable in its own right. [D1/W-2 (Min: Poor)/<em>Sex-Changed</em>/<b>Protective Talisman</b>]</p>`,
	},
	1830: {
		index: 1830,
		text: `<p>Half-dead from thirst, you did not notice anything strange about the oasis you stumbled into. But as soon as you drink the sweet, cold water, you feel a feverish chill. When the tingling fades, you find that your gender has been changed! You hasten to a cousin's home in a nearby village and implore their assistance.</p>
<p><b>No Skill:</b> They provide you with clothes suitable to your new condition and help you create a new identity. A couple weeks of this and you've learned more about the opposite sex than you ever hoped to. This inside information could prove very useful if you ever recover. [S1/Seduction/<em>Sex-Changed</em>]</p>
<p><b>Acting and Disguise:</b> It takes a lot of work, but with makeup and props you are able to alter your external appearance and mask your voice enough to convince most people that you are still as you were. You manage to keep up the façade long enough for the magical effect to fade. In the meantime, you have learned to take much greater care of your appearance. [S1/Appearance/Lose <em>Sex-Changed</em>]</p>`,
	},
	1831: {
		index: 1831,
		text: `<p>You are traveling with your beloved to visit her parents when you stop at a small desert oasis. She wishes to wash the dust of the trail away with a quick dip in the cool waters of the spring. Minutes later, a young man with familiar features stands before you, tears streaming from his eyes. The love of your life has just been transformed into a man!</p>
<p><b>No Skill:</b> Your heart cannot bear the pain you see in your beloved's eyes. You also bathe in the waters of the sex-changing spring so that you will both share the curse until a cure can be found. [S1/<em>Sex-Changed</em>]</p>
<p><b>Enduring Hardship:</b> A traveling imam happens to visit the oasis later that night. Upon hearing your tale, he tells you of a cure, but one which is rather difficult to achieve. You must forego all other drink for an entire month, instead drinking nothing but the water of the cursed pool. To your amazement, the cure works. [D1/S1/Lose <em>Sex-Changed</em>]</p>`,
	},
	1832: {
		index: 1832,
		text: `<p>Half-dead from thirst, you approach the spring with caution. The foul water in the last oasis led to the death of two of your companions. You fear the worst. Carefully examining the water, you see no sign that it will cause you harm. Finally, you dare to drink. To your shock and dismay, you discover that it is the sex-changing spring of legend!</p>
<p><b>No Skill:</b> You remember a tale of someone who had suffered a similar fate. It was said that prayer at a particular shrine in a far distant land would remove the terrifying curse. You decide to try it for yourself. [D1/S1/<em>Sex-Changed</em>/Have another player move you to any city space]</p>
<p><b>Appearance:</b> As you kneel by the pool, tears streaming from your eyes, you feel a gentle hand upon your brow. A magnificent girl, made entirely of water, stands before you. It is the spirit of the spring! Though mute, she communicates to you her regret for having inflicted such a fate upon you. She agrees to free you if you will spend a week in her company. After the week passes, you are returned to your natural form, but your heart is heavy as you turn to leave. [D1/Lose <em>Sex-Changed</em>/<em>Love Struck</em>]</p>`,
	},
	1833: {
		index: 1833,
		text: `<p>What cruel fate! Your heart was stolen by the radiant figure you encountered in the square, but you would learn that little is as it seemed to be. For your newly beloved was in fact the victim of a wicked magic: a sex-change spring!</p>
<p><b>No Skill:</b> The contradiction of falling in love with one who is actually the same sex as you weighs heavily on your soul. [S1/<em>Grief Stricken</em>]</p>
<p><b>Scholarship:</b> Though you know that there is no romance in your future together, your love for this victim of fortune drives you to locate a cure. After much research in dusty tomes of forgotten lore, you uncover the secret you seek—that the spring is not one of changing sex, but of removing curses, and the one you love was actually born in the body you see now! She must have been cursed as a very young child! [D1/S1/Magic/<b>Beloved</b>]</p>`,
	},
	1834: {
		index: 1834,
		text: `<p>You and your companions camp near the edge of an oasis. While you are attending the camels, the others go to the spring to slake their thirsts. When you hear cries of panic, you rush into the lush oasis to discover that they have all been transformed by the sex-changing spring!</p>
<p><b>No Skill:</b> One of your companions, now a learned old woman, tells you of a possible cure. It will take you some time to locate the rare and valuable herb, but you swear to your friends that you will do it. [D1/Scholarship/<em>Under Geas</em>]</p>
<p><b>Wilderness Lore:</b> You're in luck! The most learned member of your party knows of a certain herb that can reverse the terrible curse, and your experience in the wild has taught you well were to locate the valuable plant. It is the work of but a day and you have collected ample supplies to reverse the magic. [S1/Luck]</p>`,
	},
	1835: {
		index: 1835,
		text: `<p>When you drank the cool, sweet water of the spring, you never imagined that it would change your gender! But truly there is no might and majesty save with Allah, for if you had not been thus altered, you would never have been able to assist your childhood friend. The cruel Vizier of this land who had imprisoned him would have recognized you immediately, but now you seem a completely different person!</p>
<p><b>No Skill:</b> Though you cannot convince the Vizier to release your friend, your altered form does enable you to learn certain secrets of the court that would embarrass the sultan if they should become known to the public. Thus blackmailed, the Sultan has no choice but to release your friend. You both quickly leave the kingdom before he changes his mind. [D1/S1/<em>Sex-Changed</em>/Have another player move you exactly two spaces in any direction]</p>
<p><b>Seduction:</b> Though it raises bile in your throat, you realize that you are now in a perfect position to convince the Vizier to release your friend. You are careful to allow him nothing but promises, and you flee as soon as your friend is free. Best you never return to that kingdom. [D1/<em>Sex-Changed</em>/<em>Outlaw</em>]</p>`,
	},
	1836: {
		index: 1836,
		text: `<p>Legends of the mysterious rhinoceros have intrigued you for some time. You decide you must see this fabulous creature for yourself. You decide that the best way to find one is by hiring a guide, and you set about negotiating a good price with a friendly native.</p>
<p><b>No Skill:</b> The guide takes your money and leads you out into the wilderness. Two days later you wake up to discover that the guide has disappeared, leaving you in alone in the wild! [S1/<em>Lost</em>]</p>
<p><b>Enduring Hardship:</b> Your guide leads you deep into the wild, pushing you at a hectic pace. You struggle to keep up. But a week later, you are finally rewarded with a glimpse of the incredible animal, calmly feeding on the grasses of the veldt. Money well spent! [S1/Wilderness Lore]</p>`,
	},
	1837: {
		index: 1837,
		text: `<p>During your wanderings, you come across a group of men hunting the mythical rhinoceros. You are intrigued by the tales you have heard of this strange animal, and wish to join them on their hunt.</p>
<p><b>No Skill:</b> The men agree to let you accompany them after you offer to provide supplies for the journey. You are delighted when they find the animal's tracks a few days later. The creature proves to be exceptionally strong and dangerous, and it takes all of your skill and ability, along with that of your companions, to finally fell the mighty beast. [D1/S1/W-1 (Min: Penniless)/Weapon Use]</p>
<p><b>Storytelling:</b> The men are impressed by your tales of hunting and exploration and decide that you would be a valuable addition to their expedition. But though you tell a convincing tale, your knowledge in the field proves to be far less than they anticipated. Though they come to mock you, their derision proves to be a valuable incentive to learn as much as you can in the field. [S1/Wilderness Lore/<em>Scorned</em>]</p>`,
	},
	1838: {
		index: 1838,
		text: `<p>You find a band of men who have killed an enormous rhinoceros. You examine the remains, finding particularly intriguing the creature's bizarre horn.</p>
<p><b>No Skill:</b> One of the older hunters tells you a fascinating tale about the rhino and its horn. Far to the east, he says, doctors use the powder of the horn to ease fevers and treat the "falling sickness." You trade him a handful of coins for a sample of the horn in case you find a use for it in the future. [S1/Scholarship]</p>
<p><b>Bargaining and Evaluation:</b> You realize that the rarity of the rhino may make its horn as valuable as the ivory tusks of elephants. After a bit of haggling, you convince the hunters to let you take the horn. [D1/W+1 (Max: Rich)]</p>`,
	},
	1839: {
		index: 1839,
		text: `<p>According to the local villagers, there is a stretch of river nearby where the fabled rhinoceros can often be found drinking and bathing. Intrigued by the tales you have heard about this animal, you decide to investigate.</p>
<p><b>No Skill:</b> You approach the river bank but slip and splash noisily into the water. The rhino is startled by your noise and immediately charges you! Fortunately for you, the animal has poor eyesight, and after knocking you unconscious apparently cannot find you to inflict any more damage. [S1/<em>Wounded</em>]</p>
<p><b>Stealth and Stealing:</b> Cautiously, you approach the mysterious animal. You have heard that it has acute hearing but poor vision. Apparently, the tales are true, as you are able to approach close enough to touch its thick, leathery hide unnoticed. You praise the Creator that can design such fascinating creatures, and thank Him for giving you an opportunity to see one yourself. [D1/S1/<em>Blessed</em>]</p>`,
	},
	1840: {
		index: 1840,
		text: `<p>Responding to a plaintive sound in the brush, you discover a small rhinoceros cub, apparently lost. You realize that it would make a fabulous gift for the local Sultan. You attempt to capture it.</p>
<p><em>Roll two dice, adding one each for Wilderness Lore, Stealth and Stealing, and Quick Thinking:</em></p>
<p>❖ 2–5: As you approach the cub with a net, you hear a thundering sound behind you. It is the small animal's mother! You quickly decide that an angry mother is too dangerous and let the cub go. [S1/Wisdom]</p>
<p>❖ 6–9: The cub puts up a fight, biting your arm when you try to force it into the net. The wound gets red with infection, and you soon find that you are running a high fever. [S1/<em>Diseased</em>]</p>
<p>❖ 10+: You manage to corral the little rhino into the net without serious injury. The Sultan is astounded by the incredible gift you have given him, and raises you to a position of honor in his court. [D1/S1/Courtly Graces/<em>Vizier</em>]</p>`,
	},
	1841: {
		index: 1841,
		text: `<p>Somehow you have angered a rhinoceros, and now it is charging toward you! You flee in terror, desperate to find some shelter. Up ahead, you see a tumbled pile of marble and granite. It's some kind of ruin!</p>
<p><b>No Skill:</b> You dive into the shadows of the rocks just as the massive animal thunders past. You wait in the darkness for a few hours until you are sure the rhino has moved on before sneaking away quietly. [S1/Stealth and Stealing]</p>
<p><b>Luck:</b> You hide from the rhino in the interior of the ruin. While you are waiting for the curious animal to move on, your curiosity drives you to search the pile. Under a loose slate stone, you find a hidden chamber. Inside you find some time-dried bones clutching a shining object. [D1/S1/<b>Treasure</b>]</p>`,
	},
	1842: {
		index: 1842,
		text: `<p>You have decided to investigate the rumors you have heard of a fantastic creature known for its armored hide and a weapon for a snout. You know that you need a reliable guide if you are going to find the mythical creature.</p>
<p><b>No Skill:</b> The natives look at you with scorn and derision. They refuse to help you look for the rhinoceros. Angry at their poor treatment, you set out on your own. Before long you track down the rhino on your own. After watching the magnificent creature for an entire day, you return to civilization with a new tale to tell. [S1/<em>Determined</em>]</p>
<p><b>Appearance (mandatory):</b> The guide looks at you and decides that you would be useful on a rhino hunt. He leads you into the wilderness and asks you to call to the rhino with loud noises. You oblige, not realizing that your true role is rhino bait! At the last moment of the great creature's charge, you dive to the side while it rushes past you. Your treacherous guide is not as fast on his feet as you. His scream of terror tells you what his final fate was meant to be. [D1/S1]</p>`,
	},
	1843: {
		index: 1843,
		text: `<p>A rampaging rhino has trapped you in the branches of a large tree. After nearly an hour clinging to a branch, you see some travelers in the distance. Desperately you wave at them for help.</p>
<p><b>No Skill:</b> The travelers are frightened by the size of the creature at the base of the tree. They quickly head the other direction, leaving you to your fate. You spend the next night and day in the shelter of the tree, until the animal finally leaves you in peace. [S1/Enduring Hardship]</p>
<p><b>Seduction:</b> You can see that the travelers are intimidated by the beast. You realize that you need to promise them something valuable if you are going to convince them to help you. Sadly, you left your valuables in town when you went out to seek the rhino. Perhaps you can think of something else that might interest them... [S1/Beguiling]</p>`,
	},
	1844: {
		index: 1844,
		text: `<p>In the middle of the night, you are awoken by the smell of burning grass. You realize that a wildfire has engulfed your camp! Coughing on the smoke, panic begins to seize your heart as you can see no route of escape. You call out for anyone to help you. Suddenly through the choking smoke, you see a massive beast approaching!</p>
<p><b>No Skill:</b> To your amazement, the massive rhino begins stamping out the fire with his enormous feet. What wonders the world possesses! Surely the being that created such a world is truly magnificent! You are humbled to live in such a creation! [D1/S1/Piety]</p>
<p><b>Scholarship:</b> Between the fire and the charging rhino, you decide to take your chances with the flames. Plunging into the fire, you emerge from the far side, lightly singed but safe. [D1/S1/Luck]</p>`,
	},
	1845: {
		index: 1845,
		text: `<p>You hear a scream of terror from the other side of the brush. You run to investigate and see a woman running with a child in her arms. Behind her you see a frightening sight: a rhino charging straight towards her!</p>
<p><b>No Skill:</b> You remember hearing that the rhino has poor eyesight but magnificent hearing. You hope that you might be able to distract the beast by making loud noises. Yelling at the woman to be quiet, you shout and holler and throw rocks towards the charging rhino. The confused beast is fooled by your noise, and charges towards you instead. Fortunately, you are able to dive into a shallow ravine and the half-blind animal continues charging into the plain. [D1/S1]</p>
<p><b>Weapon Use:</b> Drawing your bow, you fire an arrow towards the rampaging beast. It glances off the creature's armored hide, barely scratching the surface. Apparently, the unexpected pain is enough to distract it from its course, and the woman escapes while the puzzled creature tries to locate the cause of the pain. [S1/Quick Thinking]</p>`,
	},
	1846: {
		index: 1846,
		text: `<p>You find a crippled huntsman leaning against a tree. He tells you of his encounter with a ferocious rhinoceros. Though he is no longer able to hunt, he is determined to get his revenge on the creature that left him crippled. He has devised a trap for the animal, but he needs someone to lure it in.</p>
<p><b>No Skill:</b> You try to lure the great beast into the trap with noises and gestures, but it seems too cunning to fall for your ruse. Frustrated by your failure, you return to the huntsman, but he has succumbed to his wounds. [S1/<em>Grief Stricken</em>]</p>
<p><b>Acting and Disguise:</b> You discover that the rhino is too crafty to be lured directly into the trap. You are brought to mind of tales of the animosity between rhinos and elephants. You hastily construct a mock elephant, and, imitating its noises, you enrage the rhino. As it charges you, you leap across the trap pit, into which the rhino tumbles with a sickening sound. The dying huntsman thanks you with a map to his greatest discovery. [D1/S1/Opportunity to enter the Valley of Diamonds]</p>`,
	},
	1847: {
		index: 1847,
		text: `<p>The youngest son of the Sultan asks you to help him hunt the most dangerous creature in the kingdom: the spear-nosed rhinoceros. Before you depart, the Sultan warns you that whatever fate befalls his son will befall you as well.</p>
<p><b>No Skill:</b> Despite your efforts, you and the prince are unable to locate any rhinos in the area. Disappointed, but safe, you return to the palace. [S1]</p>
<p><b>Wilderness Lore (mandatory):</b> With your superior tracking skills, you easily find one of the mysterious rhinos. Despite your warnings, the prince attacks the beast.</p>
<p><em>Roll two dice:</em></p>
<p>❖ 2: To your dismay, the prince is trampled to death. You flee the kingdom in fear for your life. [D-1/S1/<em>Outlaw</em>/<em>Pursued</em> (SOLDIER)]</p>
<p>❖ 3–4: The prince is not a skilled hunter, and you are barely able to save him from the dangerous animal. The Sultan is furious about the wounds the prince endured, and claps you in irons for your negligence. [D-1/<em>Enslaved</em>]</p>
<p>❖ 5–9: Despite the prince's bumbling, you manage to drive the creature off before it harms him. But he is furious that you allowed his quarry to escape, and the Sultan orders you expelled from the kingdom. [S1/Have another player move you exactly two spaces in any direction]</p>
<p>❖ 10+: You and the prince together are able to capture the animal, and he proudly returns it to the palace, where it is added to the Sultan's menagerie. The Sultan is pleased and rewards you with generous gifts. [D1/S1/W+2 (Max: Rich)]</p>`,
	},
	1848: {
		index: 1848,
		text: `<p>You are awakened from a sound sleep by the Sultan's guards, who bind your hands and drag you through the city to an expansive cell with dozens of other sleepy and distraught strangers, who all have no notion why they have been taken. After a time, a guard arrives to announce that the sultan's son has been murdered, and the Vizier has denounced all outsiders as traitorous dogs. Each person will be tortured in turn to reveal the guilty party. Several wretches fall to the ground in horror; others rail against the injustice. You kneel and raise your arms to the heavens: "Allah, Who is all wise and compassionate to the true believers, take notice of our plight and deliver us from this wicked Vizier's grasp."</p>
<p><b>No Skill:</b> Your pleas have no more effect than the raging, the begging, or the sobbing of the others. You are taken in turn and the coals are applied to your limbs. The pain is terrible and unhinges your mind. [D1/<em>Insane</em>]</p>
<p><b>Piety:</b> Your passion and grace are overwhelming. The others join your cry as they kneel down besides you. The guards are disturbed, and cease removing prisoners to the torture chambers. In time, the Vizier arrives, screaming at the guards for their dereliction of duty. His face is red and his manner nearly incoherent. When he sees you at the center of the blessed throng, his mind snaps. "Kill them, kill them all!" he shrieks. Suddenly, he collapses, life fled from him body. Taking this as Allah's work, the guards release the prisoners. [D2/S1/Luck]</p>`,
	},
	1849: {
		index: 1849,
		text: `<p>The Sultan's jeweled crown has been stolen! The Vizier advises the sultan that it must have been done by someone with great skill, for the crown was secured in a locked and guarded vault. He recommends that all foreigners of renown be imprisoned and tried, torturing them if necessary. The Sultan agrees.</p>
<p><em>If you have no more than S4 or D4:</em> You kneel before the Vizier, begging for your life. Luckily, you are considered too insignificant to be imprisoned. You are simply banished from the city. [S1/<em>Outlaw</em>]</p>
<p><em>If you have S5+ or D5+:</em> The Sultan's soldiers, along with the Vizier, seek you out and seize you. Your pleading does not help at all and you will be tried as a thief. While in prison, a robed figure visits. "I am here to aid you," she whispers. "I have evidence that the Vizier is behind the theft. It is not my place to challenge him, for I am his betrothed. You must act in my place at your trial. Listen closely." She details the damning knowledge, and names several who will corroborate the Vizier's guilt.</p>
<p><b>No Skill:</b> Your presentation at trial is poorly delivered, and even more poorly received. By accusing the Vizier, you place yourself in far worse position. [D1/<em>Imprisoned</em>]</p>
<p><b>Scholarship, Courtly Graces:</b> Through erudite reasoning and cultured staging, you present a defense both well-executed and convincing. The evidence against the Vizier is truly damning, and the Sultan's anger toward the disloyal servant is severe. He rescinds the promise of his daughter to the Vizier and orders him executed. The daughter—none other than your prison visitor!—steps forward and confesses herself the source of your information. The Sultan sees the bond between the two of you and recommends that you stay with her. You are not so foolish as to refuse. [D1/S1/<em>Married</em> (or <em>Robe of Honor</em> if already <em>Married</em> or female)/<em>Vizier</em>]</p>`,
	},
	1850: {
		index: 1850,
		text: `<p>Whispers start to circulate that the sultan is insane. He appears at random in various places, making odd demands, issuing contradictory orders, condemning innocents to death, and sending soldiers into the desert after phantoms. At other times, he conducts business as usual and seems the sane, blessed ruler who is so beloved by the masses. You are unfortunate enough to witness one of his violent appearances. As you scamper into hiding, you notice a strange glow about the Sultan's neck. In a trice, you realize the Sultan has been usurped by his own conniving Vizier by means of an enchantment! You bravely step forward, attracting the ruler's attention with a loud prayer: "Allah, your work is betrayed and deceived. You will is thwarted and must be restored. I call upon you to aid me in this task."</p>
<p><b>No Skill:</b> The Vizier laughs maniacally and orders his guard to beat you senseless for your disrespect. As you succumb to the pain, he loudly proclaims that Allah has forsaken you and any who challenge his actions. [D1/<em>Wounded</em>/<em>Fated</em>]</p>
<p><b>Magic:</b> As the Sultan approaches you in a rage, by a simple charm you cast off his spell of disguise, revealing to all the Vizier! He has been impersonating the Sultan to sow discord and weaken his rule. The wicked man seeks to break the love of the people for their ruler and stage a coup. Guided by Allah, you have revealed that plot and brought the wicked one to his doom. The Sultan gratefully awards you the Vizier's library, where you find several tomes of magical lore. [D2/S1/Magic]</p>`,
	},
	1851: {
		index: 1851,
		text: `<p>The other has salvaged many fine goods from shipwrecks and is looking for a business partner to help him sell the goods among the surface people. The other is certainly cunning, but you feel as though your skills could make the other's endeavors that much more successful. You agree to an alliance with him. The other gives you a few crates of fine pottery to sell.</p>
<p><b>No Skill:</b> You do sell the fine pottery very quickly. However, the other berates you for not getting a higher price, and does no further business with you. [S1/W+1 (Max: Rich)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> A distinctive pattern on the plates and lamps leads you to investigate their origin. You soon come to realize that the merman has, himself, caused many of the wrecks he has "salvaged." You arrange for the other to come to the surface on the pretense of making a large sale, but when he arrives, he is greeted by a veritable army of the merchants he has robbed. The merchants reward you handsomely for your honesty. [D1/S1/W+2 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	1852: {
		index: 1852,
		text: `<p>Despite his attitude and business practices, the other has a successful trade business—selling undersea wonders to locals. You think that you can expand his business outside of the local region. There are but a few routes to the rich, if less cultured, nations of the west, and you know of good ways to use them.</p>
<p><b>No Skill:</b> You arrange with the other to create trade arrangements. Business is good. [D1/W+1 (Max: Princely)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> The other sees the wisdom of your plans and agrees to do business with you, teaching the business of trade by sea as well. [D1/W+2 (Max: Princely)/Seamanship]</p>`,
	},
	1853: {
		index: 1853,
		text: `<p>The other's trade business is failing; though the goods of his people are wondrous, his skills with "landlubbers" are atrocious. You think that perhaps you can help.</p>
<p><b>No Skill:</b> It is of no use; the other is stubborn, his hatred of the surface people so deep that he cannot hide it. You abandon the other, mourning the loss of potential profit from the business relationship. [D1]</p>
<p><b>Courtly Graces, Beguiling:</b> You are able to help the other's skill in dealing with other people, though you know that it is a facade: he is not fond of surface people and it is hard for him to be nice to them. You are able to make some profit from the relationship, but soon his anger strains your relationship and you decide to leave him before someone does something regrettable. [D1/W+3 (Max: Princely)/Bargaining and Evaluation]</p>`,
	},
	1854: {
		index: 1854,
		text: `<p>Your attempt at a fair exchange of services and goods was never to be as the other has different plans for you. He unsheathes a very large scimitar and attacks!</p>
<p><b>No Skill:</b> Unprepared for such an assault, you are barely able to defend yourself. After a few strokes, he draws blood, and this seems to satisfy him. "I have upheld my faith and now have no need to continue." He departs, and you are relieved, if mystified. [D1]</p>
<p><b>Weapon Use, Luck:</b> You meet his blade with your own. The crash of noise brings bystanders, including some guards. The other quickly departs and you are hailed a hero, for the other, having taken leave of his senses, has been menacing innocents for the past month. [D2]</p>`,
	},
	1855: {
		index: 1855,
		text: `<p>You attempt to deal with the other to your benefit, but he grows ever more angry. "Why should I not take everything?" he says, pointing a scimitar in your face. You are in no position to argue. [D1/W-1 (Min: Penniless)]</p>`,
	},
	1856: {
		index: 1856,
		text: `<p>The other cries to the heavens and attacks you as you speak.</p>
<p><em>You may flee or stand your ground:</em></p>
<p><em>If you flee:</em> The other's attack hurts you, but you escape, knowing that you will see him again. [D1/<em>Wounded</em>/<em>Pursued</em>]</p>
<p><em>If you stand your ground:</em> You kneel on the ground and offer a prayer to Allah. The conviction in your voice is such that the other wavers, then soon joins you. [D2/Piety]</p>`,
	},
	1857: {
		index: 1857,
		text: `<p>Something about the other's sinister gaze makes your blood boil, so you begin lashing him with your horse crop.</p>
<p><b>No Skill:</b> Who knew what muscles were hidden beneath those rags? In the flash of an eye, the other has stripped your crop from your hands, and it's you getting the beating! [S1/<em>Wounded</em>]</p>
<p><b>Wilderness Lore:</b> The strength and speed of the other surprises you, but you remember an encounter you once had with a surly gorilla. Using the same tactics, you escape the other unhurt. [D1/Quick Thinking]</p>`,
	},
	1858: {
		index: 1858,
		text: `<p>The disgusting creature dared to touch your fine robes! Certainly a good beating will teach him his place!</p>
<p><b>No Skill:</b> You land blow after blow on the sniveling form, but somehow it reaches out to touch your bare skin. You feel... different. [S1/<em>Accursed</em>]</p>
<p><b>Bargaining and Evaluation:</b> As you are about to deliver a fine beating, you realize that the rags worn by the other were once fine silks! Your heart turns to mercy and, after long conversations you learn of the miserable other's unfortunate fate. [D1/S1/Wisdom]</p>
<p><b>Seamanship:</b> As you begin to vent your anger on the other, you recognize him as a wanted pirate! Seizing him by the neck, you deliver him to the magistrate for the reward. [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	1859: {
		index: 1859,
		text: `<p>Such rubbish litters the street. A sound beating should get the other to move along.</p>
<p><b>No Skill:</b> The powerful other doesn't seem to like being beaten. He decides to show you why. The crowd seems most amused by the sudden turn of events. [D-1/S1/<em>Scorned</em>]</p>
<p><b>Luck:</b> The other proves far too strong for you, and takes hold of your rod as if to beat you in return. Fortune smiles on you, however, as a troop of the Sultan's guards happen along in time to save you from a severe thrashing. [D1/S1]</p>`,
	},
	1860: {
		index: 1860,
		text: `<p>The other appears far too dangerous to risk a simple mugging, but you think you might be quick enough to grab his purse without him noticing.</p>
<p><b>No Skill:</b> You wait until the other is distracted by a passing maiden. Quick as a viper, your hand snaps out and you take hold of the purse. The other never knew you'd been there! [D1/W+1 (Max: Poor)/Stealth and Stealing]</p>
<p><b>Seduction (mandatory):</b> As you reach for the other's purse, his hand whips out to grab your wrist. Seeing murder in his eyes, you offer whatever he asks for your release. He is swayed by your offers, but afterwards you feel somehow unclean. [D-1/<em>Diseased</em>]</p>
<p><b>Seamanship:</b> You had planned to steal his purse, but you realize that he is sitting across the horn of a narwhal! The Sea-Unicorn's horn is extremely valuable as a cure for many ailments. When the other is distracted by a passing maiden, you secret the horn away. [D1/S1/Your choice: Either W+1 (Max: Princely) OR lose all <em>Accursed</em>, <em>Beast Form</em>, <em>Diseased</em>, <em>Ensorcelled</em>, <em>Insane</em>, or <em>Sex-Changed</em> statuses]</p>`,
	},
	1861: {
		index: 1861,
		text: `<p>You will need help if you are going to overcome the menacing other. You recruit a couple of rowdies in a nearby tavern.</p>
<p><b>No Skill:</b> The other sees you approach and decides that the odds are against him. Before you can react, he flees into a darkened alley. Your "allies" lose heart at sight of the darkness, and you are left empty-handed. [S1]</p>
<p><b>Wilderness Lore:</b> Dangerous prey like the other requires caution. Using tactics you learned when hunting tigers, you instruct your allies well. The other is surrounded and quickly overcome. [S1/W+1 (Max: Respectable)]</p>`,
	},
	1862: {
		index: 1862,
		text: `<p>The other is treated with fear and superstition by the locals, so you know that no one will come to his aid when you rob him.</p>
<p><b>No Skill:</b> As soon as you make your move, you realize why the locals fear this one—he is an awe-inspiring and terrible magician! [D-1/S1/Wisdom/<em>Beast Form</em>]</p>
<p><b>Scholarship:</b> You recognize certain arcane symbols on the clothes of the other. You will need protective magics to rob this one!</p>
<p><em>If you have Magic:</em> You cast a protective spell and turn the other's curses against him. His magical equipment—mere beads and baubles—sell quite well. [D1/S1/W+1 (Max: Rich)]</p>
<p><em>If not:</em> You decide it's best to let this one go. [S1]</p>`,
	},
	1863: {
		index: 1863,
		text: `<p>You wait for the other to step into a dark alley. Stepping in behind him, you bring a heavy earthen jar onto his head. Grabbing his sack, you flee into the twisted streets of the town.</p>
<p><b>No Skill:</b> Finally safe, you empty the sack to find a collection of worthless junk. Cursing your luck, you seek more profitable prey. [S1]</p>
<p><b>Seamanship:</b> You pour out your take. Most of it has no value, but your heart leaps when you recognize a coded chart! You're not sure, but you think it shows the route to the mysterious Undersea Kingdom! [D1/S1/Opportunity to enter the Undersea Kingdom]</p>`,
	},
	1864: {
		index: 1864,
		text: `<p>You look around to make sure nobody is watching. When the opportunity appears, you grab your quarry's basket and vanish into the twisting alleys.</p>
<p><b>No Skill:</b> You find a few trinkets worth selling. [S1/W+1 (Max: Poor)/Stealth and Stealing]</p>
<p><b>Bargaining and Evaluation:</b> You discover that the other had many trinkets in high demand at a nearby village. A few hours later, you've traded your way to a tidy little profit. [D1/W+2 (Max: Rich)]</p>
<p><b>Scholarship:</b> You pick through the wretched belongings of the other. At first you think that there is nothing of value, but hidden among the refuse is a wondrous item! [D1/S1/<b>Treasure</b>]</p>`,
	},
	1865: {
		index: 1865,
		text: `<p>You're certain that the time is right to strike, but as soon as you knock the other out, a patrol of guardsmen appear!</p>
<p><b>No Skill:</b> You are immediately arrested for theft. Perhaps a cold night in the dungeon will teach you better! [S1/<em>Imprisoned</em>]</p>
<p><b>Appearance (mandatory):</b> When the guards come to arrest you, they are shocked to find that you look exactly like their prince! Worried that you might use your appearance against him, he immediately banishes you from the kingdom. [S1/<em>Outlaw</em>]</p>
<p><b>Seduction:</b> The guards arrest you for your crime. During your trip to the dungeons, the captain becomes so enamored with your charms, he decides to take you home instead! [D1/S1/<b>Beloved</b>]</p>`,
	},
	1866: {
		index: 1866,
		text: `<p>How dare that odorous wretch attempt to use hypnotic powers on you! You will teach him a lesson he'll never forget!</p>
<p><b>No Skill:</b> Once you start the beating, many victims of the other come to join you. It seems he has been misusing his powers for some time! [D1/S1]</p>
<p><b>Stealth and Stealing:</b> As you rain blows down on the other, you suddenly realize that his powers could be very useful. Staying your hand, you apologize for your anger and convince him to help you relieve some of the locals of their heavy purses. [D1/W+2 (Max: Rich)/Beguiling]</p>`,
	},
	1867: {
		index: 1867,
		text: `<p>You raise your hand to strike the other, when he looks deeply into your eyes.</p>
<p><b>No Skill:</b> You completely forget what you intended to do. Feeling somewhat foolish, you stammer an apology and wander off, confused. [S1]</p>
<p><b>Seamanship:</b> You realize that the other is trying to use a hypnotic power on you, not unlike that of the dreaded sirens! You remember a tale of sailors blocking their ears against the siren's song, so perhaps the same strategy will work here. You tightly close your eyes, and feel the other's hold on your mind vanish. It's hard to thrash someone with your eyes closed, but you manage. [D1/S1/Luck]</p>`,
	},
	1868: {
		index: 1868,
		text: `<p>Heedless of the warnings you were given, you strike the other a mighty blow with your truncheon.</p>
<p><b>No Skill:</b> The other glares angrily into your eyes. In a moment you drop your club and stand motionless. Despite your desire, your feet take on a mind of their own! [S1/<em>Ensorcelled</em>]</p>
<p><b>Bargaining and Evaluation:</b> The other has some kind of hypnotic control over the crowd! As soon as you lay hands on him, they turn on you as if in a trance. Against such hopeless odds, you are forced to plead for your life. The other agrees to accept a service in exchange for sparing you. [D-1/S1/<em>Under Geas</em>]</p>`,
	},
	1869: {
		index: 1869,
		text: `<p>When you learned that the other was the leader of a vile Magian cult, you knew that swift action would be needed. When you learned that he also had powers of hypnosis, you knew that it would be dangerous indeed.</p>
<p><b>No Skill:</b> Trusting to Allah to protect you, you proceed directly to the Magian's lair, weapon in hand. Somehow, you never actually reach it. You don't know how you came to be in this wilderness, but you'd best find a way out of it. [S1/Wilderness Lore/<em>Lost</em>]</p>
<p><b>Scholarship:</b> You know that hypnotists must be able to look into your eyes in order to mesmerize you. You protect yourself with a cleverly designed mask. When you attack the Magian, his powers cannot prevent his execution. [D1/S1/Quick Thinking]</p>
<p><b>Seamanship:</b> You will have to be careful to approach the Magian unseen, or he will use his powers against you. Fortunately, he lives near a large lake, so you can reach him by boat undetected! Caught by surprise, the other is quickly overcome by your strength of arms. There is no might or glory but in Allah! [D1/S1/<em>Blessed</em>]</p>`,
	},
	1870: {
		index: 1870,
		text: `<p>The other tricked you with his mind powers and made a fool of you in public. Such an insult cannot be allowed to stand. You resolve to get your revenge.</p>
<p><b>No Skill:</b> Now that you know what the other is capable of, you are prepared to deal with his dark powers. You lay in ambush outside his lair, waiting for your opportunity to strike. When he arrives, you catch him by surprise, dispatching him and his two guards with ease! [D1/S1/Weapon Use]</p>
<p><b>Seduction:</b> You know that you cannot face the mesmeric powers of the other, but perhaps you can convince some locals to provide a distraction. Using your wiles and promises of future entertainments, you charm a group of bravos. Outnumbered and alone, the other cannot entrance them all, and you are able to sneak up behind him and strike. [D1/Stealth and Stealing]</p>`,
	},
	1871: {
		index: 1871,
		text: `<p>As soon as the other looks you in the eye, you draw your weapon and attack. You don't even know why.</p>
<p><b>No Skill:</b> You are promptly arrested for murder and sentenced to hang. As you are lead to the gallows, you see the other in the crowd, grinning an evil grin! You see now that he is a magician, and has plotted to destroy you. But Allah does not allow such evils to pass, and the rope breaks when you are hanged. You choke out that this occurrence is proof of your innocence. [D1/S1/Piety/<em>Crippled</em>]</p>
<p><b>Wilderness Lore:</b> You remember learning how to deal with dangerous cobra snakes. They also have mesmeric powers like the other is using on you. Like the cobra, the only way to be sure is to strike off his head. As soon as relieve the other of his skull, his spell on the local populace is broken. When he realizes what you have saved him from, the Sultan selects you to be his trusted advisor. [D2/<em>Vizier</em>]</p>`,
	},
	1872: {
		index: 1872,
		text: `<p>You find the other sitting in a corner, rocking back and forth and muttering in tongues. You try to make out some of what he is saying.</p>
<p><b>No Skill:</b> Whatever he is saying, you don't think it's a real language. But his voice is soothing and you soon doze off, to a sleep filled with vivid dreams that make fascinating tales. [S1]</p>
<p><b>Magic (mandatory):</b> You understand just enough of what he is saying to know that they should never have been said! The Invisible City! The empty sands! Your mind reels as his rambling reveals hidden secrets none were meant to know. [D1/<em>Insane</em>]</p>
<p><b>Seamanship:</b> You discover that the other's speech changes rapidly from one language to another. Eventually, you recognize in the babble the tongue of long-lost Atlantis! You realize a moment too late that he is casting a powerful magic spell. The world spins around you. [D1/Move to the Undersea Kingdom and have an immediate encounter]</p>`,
	},
	1873: {
		index: 1873,
		text: `<p>The other was once a renowned explorer, but something he saw in some distant land has permanently unhinged his mind. You hope that you can break through his haze to get information to help your travels.</p>
<p><b>No Skill:</b> In a brief moment of lucidity, the other manages to answer one of your questions. [S1]</p>
<p><b>Wilderness Lore:</b> Between his rambling and an occasional question you can puzzle out an answer for, you discover what he found that broke his mind. You resolve to steer clear of that area. [D1/<em>Blessed</em> (1 turn)]</p>`,
	},
	1874: {
		index: 1874,
		text: `<p>You stop to ask for directions to the next town, but clearly the one you are asking is quite mad.</p>
<p><b>No Skill:</b> You try to make out what the other is saying, but his madness just leaves you more confused. [D1/<em>Lost</em>]</p>
<p><b>Bargaining and Evaluation:</b> Just when you start to make sense from the ramblings of the other, his keeper comes to collect him. You are so interested in what the other has to say, that you pay a bribe to continue the conversation a little while longer. [D1/S1/W-1 (Min: Respectable)/Scholarship]</p>`,
	},
	1875: {
		index: 1875,
		text: `<p>You are desperate for some assistance with some manual labor, but you can find no aid save for the other. Reluctantly, you agree to pay him some coins for his efforts.</p>
<p><b>No Skill:</b> With only a small amount of correction, the other proves adequate for your needs. Praise Allah, you should learn to be less judging of others! [D1/Piety]</p>
<p><b>Wilderness Lore:</b> You discover that controlling the other is really no different from handling most beasts of burden. You find the other eager to please, and with his aid the profit from your ventures is greater than you expected. [S1/W+1 (Max: Rich)]</p>
<p><b>Seamanship:</b> After observing the other for a few hours, you realize that you have seen this kind of madness before. Sailors too long at sea have shown similar derangements. Armed with this knowledge, you are able to treat his madness. In his gratitude, he offers to join you on your quest. [D1/S1/You may lose one status of your choice]</p>`,
	},
	1876: {
		index: 1876,
		text: `<p>The man you hired for this job proves to be out of his mind. At the worst possible moment, the insanity of the other overcomes him, and he begins shouting and waving his arms.</p>
<p><b>No Skill:</b> The other draws the attention of the Vizier's guards, who promptly throw him into a cell. They throw you in too, just for being near the mad one. [<em>Imprisoned</em>]</p>
<p><b>Seduction:</b> The other's insane shouting leads the Vizier's men to arrest you both. You are dragged before him for questioning. You have heard disturbing stories of the unusual tastes of the corrupt Vizier, and with seductive words you convince him that the other is the perfect outlet for those tastes. For your aid, the Vizier releases you. [S1/Courtly Graces]</p>
<p><b>Acting and Disguise:</b> You imitate the other so exactly that the guards believe you are both mad. Rather than risk their own minds, they deposit you outside the town walls with orders never to be seen here again. [D1/<em>Outlaw</em>/Move one space in any direction]</p>`,
	},
	1877: {
		index: 1877,
		text: `<p>You have a clever idea that requires the assistance of a known madman. You are lucky enough to find one. You unleash the other on the locals, and use your clever wit to convince some of them that his madness is contagious.</p>
<p><b>No Skill:</b> Fortunately for the locals, you can also offer a surefire cure... [S1/W+1 (Max: Rich)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> One of the "victims" of the other's "illness" is none other than the Sultan himself! Once you have convinced him that you have "cured" him, he begins to trust you as no other! [D1/S1/<em>Vizier</em>]</p>`,
	},
	1878: {
		index: 1878,
		text: `<p>Behind that cheerful face there must be a plot to ruin you! Just to be safe, you begin beating the other.</p>
<p><b>No Skill:</b> After a sound thrashing, the other is much less friendly. So are the townsfolk who saw your actions. [S1/<em>Scorned</em>]</p>
<p><b>Wilderness Lore:</b> Your hunter's instincts notice the shifting eyes of the other as you lay hands upon him. He is working with somebody! Turning around, you see his partner slinking away and you give chase. When you catch him, you find that he is a wanted thief, and you turn him in for the reward. [D1/W+1 (Max: Respectable)/Quick Thinking]</p>`,
	},
	1879: {
		index: 1879,
		text: `<p>The simple-minded other insists on following you everywhere you go. It's beginning to interfere with your plans! You're going to have to frighten him off before everything is ruined.</p>
<p><b>No Skill:</b> You cuff the other soundly upon the head. He whimpers and looks at you with tears welling in his eyes. Your heart melts with regret for your callous action, but painful choices must be made. [D-1/S1]</p>
<p><b>Seamanship, Enduring Hardship:</b> Your years at sea have taught you the importance of discipline, and the hardest duty of all is correcting an errant crewman. As humanely as you can, you beat the wretch, but only enough to send him on his way. [D1/<em>Determined</em>]</p>`,
	},
	1880: {
		index: 1880,
		text: `<p>When someone is as miserable as you are, the last thing you want to see is some overly happy fool forcing his company upon you. In a fit of ire, you lash out at the other.</p>
<p><b>No Skill:</b> The severe beating you unleash upon the other has the desired effect. Now both of you are miserable. [S1]</p>
<p><b>Seduction:</b> As soon as you begin beating the other about the head, you regret your decision to act so cruelly. This simple creature has done nothing to deserve your anger. Almost immediately, you change to kindness. The other is so grateful, he agrees to show you a secret!</p>
<p><em>If you have Stealth and Stealing:</em> The other leads you to a thieves' den. While they sleep, you sneak in and claim their latest prize for yourself. [D1/S1/<b>Treasure</b>]</p>
<p><em>If you do not:</em> The other shows you a den of thieves. You report them to the Vizier, who rewards you handsomely. [D1/S1/W+2 (Max: Rich)]</p>`,
	},
	1881: {
		index: 1881,
		text: `<p>Clearly, the other is part of some scheme against you, otherwise he would not be so friendly. If you slay him, he'll never scheme against you again!</p>
<p><b>No Skill:</b> As soon as you set upon the other, his friends come to his aid. You take a few severe blows before you are able to make good your escape, but you have learned much about fighting many at once. [D1/Weapon Use/<em>Wounded</em>]</p>
<p><b>Seamanship:</b> You assail the other with your blade, but he expected such and was ready with his defense. As you duel, the rest of his gang surrounds you. Your only hope of escape is to clamber up a nearby pole. Fortunately, your experience on sailing ships has honed such acrobatic skills, and you rapidly ascend to the safety of the rooftops. [D1/S1]</p>`,
	},
	1882: {
		index: 1882,
		text: `<p>Even one more insult from the other would be far beyond what any man should be expected to endure. They may be meant in jest, but your pride has been stung too many times. Pushed to the limit, you challenge the other to a duel.</p>
<p><b>No Skill:</b> It's a good thing you got the other drunk before you started the fight! His skill with a weapon is much greater than yours. Fortunately, his good humor saves you from a death, but it will be some time before you wield a blade again. [D-1/S1/<em>Crippled</em>]</p>
<p><b>Weapon Use (mandatory):</b> The besotted fool practically throws himself on your blade. Your quest for revenge has lead to murder! You flee the town, but word of your misdeeds has reached the Sultan, who demands your head for slaying a favored jester of his. [D-1/S1/<em>Pursued</em> (SOLDIER)]</p>
<p><b>Bargaining and Evaluation:</b> You quickly realize your error, as you cannot hope to overcome the other in fair combat. Before it goes too far, you throw yourself upon the ground and beg for his mercy. The other helps you up with good humor, and leads you to the saloon for another drink. [D1/S1]</p>`,
	},
	1883: {
		index: 1883,
		text: `<p>It has taken you days to earn the other's trust. Now his guard is down and you are ready to strike.</p>
<p><b>No Skill:</b> Catching the other by surprise, you easily dispatch him with your blade. At last the blood debt is paid. [D1]</p>
<p><b>Acting and Disguise:</b> There would be little use in revenge if you end up with the other's tribe hunting you. Far better to make it look like somebody else was responsible—somebody else you have reason to despise... [D1/S1]</p>`,
	},
	1884: {
		index: 1884,
		text: `<p>Though the other is hopelessly drunk, you hope that he can be relied on for a simple task.</p>
<p><b>No Skill:</b> Somehow the other delivered a completely different message than you intended! Now you have accidentally insulted an important merchant, and your once-profitable deal has turned sour. [S1/W-1 (Min: Respectable)]</p>
<p><b>Storytelling:</b> You tell the other grand and dire tales of the horrible fates meted out by the Most High for those whose drunkenness prevented their destined work. Swallowing hard, the other swears to deliver your message to your merchant friend. [D1/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> Though the drunken fool you hired delivers the wrong message, your superior negotiation skills enable to you mend your damaged relationship with the merchants of the town. [D1/S1]</p>`,
	},
	1885: {
		index: 1885,
		text: `<p>You are told by many in town that only the other has the knowledge and skill to guide you through the dreaded Ravine of Tears. Reluctantly, you pay his price, hoping that he'll be sober before you reach your destination.</p>
<p><b>No Skill:</b> No sooner do you enter the Ravine than your drunken guide falls from his horse and breaks his skull. Now you are on your own. [S1/<em>Lost</em>]</p>
<p><b>Wilderness Lore:</b> Long before you reach the Ravine, you realize that your guide's drunkenness makes him worthless to you. You decide to find your own route. [D1/Have another player move you exactly two spaces in any direction]</p>
<p><b>Enduring Hardship:</b> You know that your only hope of success is to force the drunk to get sober. You pour out all of his wine, and listen to his cries and threats for four days. Finally, he thanks you for ridding him of his demons, and he shows you the right path. [D1/S1/Wilderness Lore]</p>`,
	},
	1886: {
		index: 1886,
		text: `<p>As soon as you approach the other, he immediately turns on you and attacks in a drunken rage!</p>
<p><b>No Skill:</b> You do not wish to harm the poor drunk, so you trip him up and make a hasty retreat. You'll have to find another lackey to hire. [S1]</p>
<p><b>Weapon Use (mandatory):</b> Before you can think, your weapon is in your hand, the other's blood dripping on the ground. "Murder!" you hear someone yell. You'd best flee before you end up warming some dungeon. [D-1/S1/<em>Outlaw</em>]</p>
<p><b>Seamanship:</b> Your years on sailing ships have taught you a few tricks for dealing with drunken crewmen. In a flash you have subdued the other. Once he has sobered up, he eagerly offers to work for you. [D1/Gain one skill of your choice]</p>`,
	},
	1887: {
		index: 1887,
		text: `<p>The wretched scoundrel deserves no mercy, whatever his condition may be! You ruthlessly batter the other.</p>
<p><b>No Skill:</b> Considering his poor health, perhaps you should have been more cautious. You accidentally slay the other and are overcome with remorse. [D-1/S1/<em>Grief Stricken</em>]</p>
<p><b>Stealth and Stealing:</b> While the other crawls towards safety, you notice he dropped his purse. Considering he is near-death, you are certain he won't need it. [S1/W+1 (Max: Poor)]</p>
<p><b>Seduction:</b> The other's child comes running out to aid his aged parent, begging you to be merciful. The beauty of the young one entrances you. Your demeanor changes from angry shouts to honeyed words in an instant. [D1/<em>Love Struck</em>]</p>`,
	},
	1888: {
		index: 1888,
		text: `<p>Convinced that the other is playing a trick on you, you decide to give him the last beating of his nearly ended life.</p>
<p><b>No Skill:</b> You have hastened the demise of the favorite plaything of a nearby sorceress. She is not amused, but decides that you will make a fine replacement. [D1/S1/<em>Ensorcelled</em>]</p>
<p><b>Wilderness Lore:</b> You realize at the last moment that your victim is not faking his injuries, and you desperately try to save him. Fortunately, a nearby sage with knowledge of the healing arts comes to your aid. Under his skilled hands, the other is saved. [D1/Scholarship]</p>`,
	},
	1889: {
		index: 1889,
		text: `<p>You are enraged by the other, who has ruined your robes with his filthy hands, and you begin to beat him mercilessly.</p>
<p><b>No Skill:</b> You did not realize how fragile the other was. After only a few blows, he lies dead at your feet. Unable to explain your actions, you are cast into the Sultan's dungeons. [S1/<em>Imprisoned</em>]</p>
<p><b>Quick Thinking:</b> The wretch was near-dead already; you have merely ended his misery. But others may not see it that way. Quickly, you slip your purse into the dead hand of the other. Shouting "Thief!" you continue beating him until the guard appears. They believe your story without hesitation. [S1/Acting and Disguise]</p>
<p><b>Seamanship:</b> Having once served as boatswain, you know how to deliver lashes without causing permanent damage. Though the other's days are numbered, it is not your hand that will bring about the hour of his demise. [D1/S1]</p>`,
	},
	1890: {
		index: 1890,
		text: `<p>Allah is merciful with those who show mercy, you have heard, so when you encounter the other, you are inclined to offer alms.</p>
<p><b>No Skill:</b> "It is too late for one such as me, but on behalf of my children, I thank you." Your heart and soul are warmed by the gratitude of the unfortunate other. [D1/<em>Blessed</em>]</p>
<p><b>Seamanship:</b> You remember from your voyages an island with miraculous healing springs. Perhaps those waters could aid the other? You arrange passage for the other on a trustworthy ship. Word of your generosity quickly spreads. [D1/S1/W-1 (Min. Respectable)/<em>Respected</em>]</p>`,
	},
	1891: {
		index: 1891,
		text: `<p>You find the other bleeding by the road. Some ruthless adventurer has beaten him nearly to death. You know that he cannot be saved, but perhaps you can make him comfortable.</p>
<p><b>No Skill:</b> You buy the other all that he needs to be comfortable for his last few days. When you return to visit him, you discover that he has disappeared! The clever charlatan has made off with your money! [S1/W-2 (Min: Poor)]</p>
<p><b>Seduction:</b> To your amazement, the other was married to a beautiful and wealthy noblewoman! You decide to try to impress the widow with your charms. After comforting her for her loss, she generously rewards your kindness. [D1/W+1 (Max: Rich)]</p>`,
	},
	1892: {
		index: 1892,
		text: `<p>The other lay in a ditch, too ill to survive. You sit and comfort him until he passes. You learn that he was a wealthy merchant before his illness cost him his health and his fortune. His greatest wish would be to see his business flourish one last time before he dies.</p>
<p><b>No Skill:</b> You conclude that it wasn't only illness that cost the other his fortune. His business is nothing but a way to lose money. You try to cut your losses. [S1/W-2 (Min. Poor)]</p>
<p><b>Bargaining and Evaluation:</b> The other has very unusual business ideas, but you see the potential in it. You are sad that he didn't live long enough to see it, but his heirs will be well cared-for. [D1/S1/W+1 (Max: Princely)]</p>`,
	},
	1893: {
		index: 1893,
		text: `<p>Surely it is mercy to end the misery of a wretch like the other. He soon would have died even if you hadn't hastened the end with your blade.</p>
<p><b>No Skill:</b> The townsfolk don't seem to agree with you. They accuse you of murder. Rather than rot in the Sultan's dungeons, you flee into the countryside. [S1/Have another player move you one space in any direction]</p>
<p><b>Bargaining and Evaluation:</b> The Sultan dislikes your callous execution. Though you are unable to justify your act to him, you are able to negotiate enough compensation to avoid the dungeon. [S1/W-1 (Min: Penniless)]</p>
<p><b>Appearance:</b> The locals are aghast at your actions. But to their minds someone with your angelic features could not truly be guilty of murder. Though they avoid you, no one seeks to punish you. [D1/Beguiling]</p>`,
	},
	1894: {
		index: 1894,
		text: `<p>Hidden deep within the other's skull is the secret that you require. You must get it before he dies, taking the knowledge with him! Taking up your truncheon, you attack him in a dark doorway.</p>
<p><b>No Skill:</b> How can you intimidate one who is so near death? The other takes his secrets to the grave. [S-1]</p>
<p><b>Seamanship:</b> Already weak, there is little the other can do to resist you. As he lies dying, you make out a few raspy words. You recognize the whispered names from your days as a sailor! With that information, you should have no trouble finding what you seek. [D1/S1/Scholarship]</p>`,
	},
	1895: {
		index: 1895,
		text: `<p>You recognize the other as a former partner who betrayed you and left you to die in the wilderness. Though he is now near death, you will not wait for the justice you deserve.</p>
<p><b>No Skill:</b> You attack the other at his home. Though you slay him, the crowd is angered by your actions. The beating you receive is a small price to pay for satisfaction. [D1/S1/<em>Wounded</em>]</p>
<p><b>Wilderness Lore:</b> By luck, the other's eyesight has faded and he does not recognize you. You devise a perfect revenge. You convince him to come with you, and you lead him to a secluded area far from town. Now he knows what it is to be left to die! [D1/S1]</p>`,
	},
	1896: {
		index: 1896,
		text: `<p>What better accomplice than one who is already near death? With promises of a miraculous cure for the other's condition, you convince him to help you relieve a certain corrupt Vizier of a family heirloom.</p>
<p><b>No Skill:</b> The other has little skill for such things, and the alarm is soon raised. When the guards are done with him, there is no one to testify against you and you escape unscathed. [S1]</p>
<p><b>Stealth and Stealing:</b> You instruct the other carefully on what he should do, and he proves capable of following your directions. In exchange for a bottle of snake oil, he hands you the heirloom. [D1/Beguiling/<b>Treasure</b>]</p>
<p><b>Seduction:</b> The other is somewhat clumsy, so you need to provide a distraction. The guards are easily swayed by your attentions and the other completes the theft. [D1/S1/<b>Treasure</b>]</p>`,
	},
	1897: {
		index: 1897,
		text: `<p>You have heard of an old sailor, near to death, who has traveled in the regions you are seeking. You hope to hire him.</p>
<p><b>No Skill:</b> You convince the other to join you on your voyage despite his failing health. Unfortunately, even a few miles on the road proves too much for him. You build a fine cairn to mark his passing. [S1]</p>
<p><b>Seamanship:</b> You don't think the other could survive the trials of a sea voyage in his condition, so you agree to buy all of his old charts and maps. [D1/W-1 (Min: Poor)/Seamanship]</p>`,
	},
	1898: {
		index: 1898,
		text: `<p>If you had known that the other was so near to death, you would not have hired him to deliver such an important message. Now he has expired in the street, and your sensitive letter may fall into the wrong hands.</p>
<p><b>No Skill:</b> There is no chance to recover your letter before it is found by the guards. Better to make an escape now before they come looking for you. [D1/Have another player move you one space in any direction]</p>
<p><b>Bargaining and Evaluation:</b> You approach the guards as they stand around the other. You offer to deal with his remains in exchange for whatever valuables you may find on him. They look at his meager rags and decide that he has nothing they would want, so they agree. You dump the body and retrieve your letter. [D1/S1]</p>`,
	},
	1899: {
		index: 1899,
		text: `<p>The proud and haughty must, on occasion, be taught humility lest their power should lead them astray. You decide to take that duty on yourself.</p>
<p><b>No Skill:</b> Unfortunately, the proud and haughty also tend to attract the weak-willed. You are unable to overcome the other's guardians, and are forced to retreat. [S1/<em>Wounded</em>]</p>
<p><b>Wilderness Lore:</b> You choose a fine location to catch the other by surprise. Leaping from the shadows, you unleash a flurry of blows upon the other. Though you would have preferred to make an example in public, at least this one knows that all power save Allah's is limited. [D1]</p>`,
	},
};
